-- Preços de compra do tabaco (PVP e custo por unidade de encomenda), das faturas da Adelaide Sousa Ferreira
-- FT 2026A2/1394 (24/08), 1462 (07/09), 1495 (14/09). A mais recente vence. Só acrescenta; só administradores veem.
create table if not exists public.tabaco_precos (
  product_id text primary key references public.products(id),
  pvp_c      integer not null check (pvp_c > 0),      -- PVP da unidade de encomenda (volume ou unidade), em cêntimos
  custo_c    integer not null check (custo_c > 0),    -- preço de compra da mesma unidade, já com o desconto
  unidade    text not null check (unidade in ('volume','unidade')),
  fornecedor text not null default '',
  fatura     text not null default '',
  data       date,
  designacao text not null default '',               -- nome do artigo na fatura
  atualizado timestamptz not null default now()
);
alter table public.tabaco_precos enable row level security;
revoke all on public.tabaco_precos from anon;
drop policy if exists "precos so admin" on public.tabaco_precos;
create policy "precos so admin" on public.tabaco_precos for all to authenticated using (public.is_admin()) with check (public.is_admin());
grant select, insert, update, delete on public.tabaco_precos to authenticated;
on conflict (product_id) do update set pvp_c=excluded.pvp_c, custo_c=excluded.custo_c, unidade=excluded.unidade, fornecedor=excluded.fornecedor,
  fatura=excluded.fatura, data=excluded.data, designacao=excluded.designacao, atualizado=now();
